fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    // We iterate p from 0..n-1, and for each p iterate q from p+1..n.
    // The first time we hit nums[p] + nums[q] == target, (p, q) is
    // lexicographically smallest by construction.
    for p in 0..n {
        for q in p + 1..n {
            if nums[p] + nums[q] == target {
                return (p, q);
            }
        }
    }
    // Given the problem assumptions, this point is never reached.
    unreachable!("No two-sum pair found, but problem guarantees at least one.")
}

